#!/bin/bash

# 🚀 Complete Expo Fix Script - Resolves all connection, asset, and auth issues
set -e

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
PURPLE='\033[0;35m'
NC='\033[0m'

echo -e "${PURPLE}🚀 COMPLETE EXPO FIX - RESOLVING ALL ISSUES${NC}"
echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
echo ""

# 1. Fix Authentication Issue
echo -e "${BLUE}🔐 Step 1: Checking Expo Authentication${NC}"
if ! npx expo whoami >/dev/null 2>&1; then
    echo -e "${YELLOW}⚠️ Not logged into Expo. Some features may require login.${NC}"
    echo -e "${BLUE}To login, run: npx expo login${NC}"
    echo ""
    
    # Create anonymous config for development
    echo -e "${BLUE}🔧 Setting up anonymous development mode...${NC}"
    cat > expo-anonymous.config.js << 'EOF'
const config = {
  ...require('./app.json').expo,
  extra: {
    ...require('./app.json').expo.extra,
    eas: {
      projectId: "anonymous-development"
    }
  },
  owner: undefined,
  slug: "local-clubhouse-dev"
};

module.exports = config;
EOF
else
    EXPO_USER=$(npx expo whoami)
    echo -e "${GREEN}✅ Logged in as: $EXPO_USER${NC}"
fi

# 2. Create Missing Assets
echo -e "${BLUE}🎨 Step 2: Creating Required Assets${NC}"
mkdir -p assets

# Check if assets already exist
if [ ! -f "assets/icon.png" ]; then
    echo "Creating default icon.png..."
    # Create a simple colored square as icon using base64
    base64 -d > assets/icon.png << 'EOF'

EOF
fi

if [ ! -f "assets/splash.png" ]; then
    echo "Creating default splash.png..."
    # Create splash screen (larger blue square)
    base64 -d > assets/splash.png << 'EOF'

EOF
fi

if [ ! -f "assets/adaptive-icon.png" ]; then
    echo "Copying icon as adaptive-icon..."
    cp assets/icon.png assets/adaptive-icon.png
fi

if [ ! -f "assets/favicon.png" ]; then
    echo "Copying icon as favicon..."
    cp assets/icon.png assets/favicon.png
fi

echo -e "${GREEN}✅ Assets directory created with default images${NC}"
ls -la assets/

# 3. Fix Metro Configuration for Better Stability
echo -e "${BLUE}⚙️ Step 3: Optimizing Metro Configuration${NC}"
cat > metro.config.js << 'EOF'
const { getDefaultConfig } = require('expo/metro-config');
const { withNativeWind } = require('nativewind/metro');

const config = getDefaultConfig(__dirname);

// Basic configuration without problematic options
config.watchFolders = [__dirname];
config.resolver.platforms = ['ios', 'android', 'native', 'web'];

// Increase timeout for slow connections
config.server = {
  ...config.server,
  enhanceMiddleware: (middleware) => {
    return (req, res, next) => {
      // Increase timeout for all requests
      res.setTimeout(300000); // 5 minutes
      return middleware(req, res, next);
    };
  },
};

// Optimize transformer for stability
config.transformer = {
  ...config.transformer,
  getTransformOptions: async () => ({
    transform: {
      experimentalImportSupport: false,
      inlineRequires: true,
    },
  }),
};

// Reduce worker count for stability
config.maxWorkers = 2;

module.exports = withNativeWind(config, { input: './global.css' });
EOF

# 4. Create Development Scripts with Better Error Handling
echo -e "${BLUE}📝 Step 4: Creating Enhanced Startup Scripts${NC}"

# Create tunnel script with authentication check
cat > scripts/start-tunnel-safe.sh << 'EOF'
#!/bin/bash
# Set file limits
ulimit -n 65536

echo "🚀 Starting Expo with tunnel (anonymous mode if not logged in)..."

# Clear caches
rm -rf /tmp/metro-* /tmp/react-* 2>/dev/null || true

# Check if logged in
if npx expo whoami >/dev/null 2>&1; then
    echo "✅ Logged in to Expo"
    CONFIG_FLAG=""
else
    echo "⚠️ Not logged in - using anonymous configuration"
    CONFIG_FLAG="--config expo-anonymous.config.js"
fi

# Start with tunnel - handles auth automatically
export EXPO_NO_TELEMETRY=1
export METRO_MAX_WORKERS=2
export EXPO_TUNNEL_SUBDOMAIN=localclubhouse

npx expo start --tunnel --clear $CONFIG_FLAG
EOF

chmod +x scripts/start-tunnel-safe.sh

# Create local development script
cat > scripts/start-local.sh << 'EOF'
#!/bin/bash
# Set file limits
ulimit -n 65536

echo "🚀 Starting Expo in local mode..."

# Clear caches
rm -rf /tmp/metro-* /tmp/react-* 2>/dev/null || true

# Check login status
if ! npx expo whoami >/dev/null 2>&1; then
    echo "⚠️ Not logged in - some features may be limited"
fi

# Start local server
export EXPO_NO_TELEMETRY=1
export METRO_MAX_WORKERS=2
export REACT_NATIVE_PACKAGER_HOSTNAME=$(ipconfig getifaddr en0 || echo "localhost")

echo "📱 Using IP: $REACT_NATIVE_PACKAGER_HOSTNAME"

npx expo start --lan --clear
EOF

chmod +x scripts/start-local.sh

# 5. Update package.json with new scripts
npm pkg set scripts.dev:safe="./scripts/start-tunnel-safe.sh"
npm pkg set scripts.dev:local="./scripts/start-local.sh"
npm pkg set scripts.login="npx expo login"
npm pkg set scripts.logout="npx expo logout"
npm pkg set scripts.whoami="npx expo whoami"

# 6. Create connection test script
echo -e "${BLUE}🔍 Step 5: Creating Connection Test Script${NC}"
cat > scripts/test-connection.sh << 'EOF'
#!/bin/bash

echo "🔍 Testing Expo Connection..."
echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"

# Test Metro bundler
echo "📡 Testing Metro bundler..."
if curl -s http://localhost:8081 >/dev/null 2>&1; then
    echo "✅ Metro bundler is running"
else
    echo "❌ Metro bundler not accessible"
fi

# Test network interfaces
echo ""
echo "🌐 Available network interfaces:"
ifconfig | grep "inet " | grep -v 127.0.0.1 | awk '{print "  - " $2}'

# Test Expo status
echo ""
echo "👤 Expo account status:"
if npx expo whoami >/dev/null 2>&1; then
    echo "✅ Logged in as: $(npx expo whoami)"
else
    echo "⚠️ Not logged in (anonymous mode)"
fi

# Check assets
echo ""
echo "📦 Asset status:"
for asset in icon.png splash.png adaptive-icon.png favicon.png; do
    if [ -f "assets/$asset" ]; then
        echo "✅ assets/$asset exists"
    else
        echo "❌ assets/$asset missing"
    fi
done

echo ""
echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
EOF

chmod +x scripts/test-connection.sh

# 7. Final summary and instructions
echo ""
echo -e "${GREEN}✅ ALL FIXES IMPLEMENTED SUCCESSFULLY!${NC}"
echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
echo ""
echo -e "${BLUE}📋 SOLUTIONS IMPLEMENTED:${NC}"
echo "1. ✅ Created missing assets (icon.png, splash.png, etc.)"
echo "2. ✅ Set up anonymous development mode (no login required)"
echo "3. ✅ Optimized Metro config with increased timeouts"
echo "4. ✅ Created safe startup scripts with auth handling"
echo ""
echo -e "${BLUE}🚀 HOW TO START:${NC}"
echo ""
echo -e "${GREEN}Option 1: Tunnel (Most Reliable)${NC}"
echo "  npm run dev:safe"
echo "  - Works without Expo login"
echo "  - Bypasses network issues"
echo "  - Generates public URL"
echo ""
echo -e "${GREEN}Option 2: Local Network${NC}"
echo "  npm run dev:local"
echo "  - Faster than tunnel"
echo "  - Requires same WiFi network"
echo ""
echo -e "${YELLOW}📱 TO LOGIN TO EXPO (Optional):${NC}"
echo "  npm run login"
echo ""
echo -e "${YELLOW}🔍 TO TEST CONNECTION:${NC}"
echo "  ./scripts/test-connection.sh"
echo ""
echo -e "${PURPLE}Ready to start development! 🎉${NC}"